import { defineTool as defineTool2 } from "npm:@lovable.dev/mcp-js@0.22.0";
import { z as z2 } from "npm:zod@^4.4.3";
var get_article_default = defineTool2({
  name: "get_article",
  title: "Get article",
  description: "Return metadata and the public URL for a specific article by its slug. Fetch the URL to read the full content.",
  inputSchema: {
    slug: z2.string().min(1).describe("Article slug, e.g. 'divorcio-online'.")
  },
  annotations: { readOnlyHint: true, idempotentHint: true, openWorldHint: false },
  handler: ({ slug }) => {
    const article = articles.find((a) => a.slug === slug);
    if (!article) {
      return {
        content: [{ type: "text", text: `Article not found: ${slug}` }],
        isError: true
      };
    }
    const result = { ...article, url: `${SITE_URL}/artigos/${slug}` };
    return {
      content: [{ type: "text", text: JSON.stringify(result, null, 2) }],
      structuredContent: result
    };
  }
});

